// Rich — Order has behaviour and enforces its own rules
public class Order {
    private final String     id;
    private       OrderStatus status;
    private final List<OrderItem> items = new ArrayList<>();
    private       Money       total;

    // Cancel knows the rule — no external service needed
    public void cancel() {
        if (status == OrderStatus.SHIPPED)
            throw new DomainException("Cannot cancel a shipped order");
        if (status == OrderStatus.DELIVERED)
            throw new DomainException("Cannot cancel a delivered order");
        this.status = OrderStatus.CANCELLED;
    }

    // Ship knows what it takes to be ready to ship
    public void ship() {
        if (status != OrderStatus.PLACED)
            throw new DomainException("Only placed orders can be shipped");
        if (items.isEmpty())
            throw new DomainException("Cannot ship an empty order");
        this.status = OrderStatus.SHIPPED;
    }

    // Adding items recalculates total — invariant maintained automatically
    public void addItem(ProductId productId, int qty, Money unitPrice) {
        if (status != OrderStatus.DRAFT)
            throw new DomainException("Cannot add items to a non-draft order");
        items.add(new OrderItem(productId, qty, unitPrice));
        recalculateTotal();
    }

    private void recalculateTotal() {
        total = items.stream()
                     .map(i -> i.unitPrice().multiply(i.quantity()))
                     .reduce(Money.ZERO, Money::add);
    }

    public boolean isCancellable() {
        return status == OrderStatus.DRAFT || status == OrderStatus.PLACED;
    }
}

