#include <string>
#include <vector>
#include <stdexcept>
using namespace std;

enum class OrderStatus { DRAFT, PLACED, SHIPPED, DELIVERED, CANCELLED };

// Rich — Order has behaviour and enforces its own rules
class Order {
public:
    // Cancel knows the rule — no external service needed
    void cancel() {
        if (status == OrderStatus::SHIPPED)
            throw runtime_error("Cannot cancel a shipped order");
        if (status == OrderStatus::DELIVERED)
            throw runtime_error("Cannot cancel a delivered order");
        status = OrderStatus::CANCELLED;
    }

    // Ship knows what it takes to be ready to ship
    void ship() {
        if (status != OrderStatus::PLACED)
            throw runtime_error("Only placed orders can be shipped");
        if (items.empty())
            throw runtime_error("Cannot ship an empty order");
        status = OrderStatus::SHIPPED;
    }

    // Adding items recalculates total — invariant maintained automatically
    void addItem(const string& productId, int qty, double unitPrice) {
        if (status != OrderStatus::DRAFT)
            throw runtime_error("Cannot add items to a non-draft order");
        items.push_back({productId, qty, unitPrice});
        recalculateTotal();
    }

    bool isCancellable() const {
        return status == OrderStatus::DRAFT || status == OrderStatus::PLACED;
    }

private:
    struct OrderItem { string productId; int quantity; double unitPrice; };

    string id;
    OrderStatus status = OrderStatus::DRAFT;
    vector<OrderItem> items;
    double total = 0.0;

    void recalculateTotal() {
        total = 0.0;
        for (const auto& i : items) {
            total += i.unitPrice * i.quantity;
        }
    }
};

